WITH rollup_totals AS (SELECT p.channel, p.status AS order_status, COUNT(*) AS rows_total, MAX(e.cost) AS max_cost FROM shipments e INNER JOIN orders p ON e.order_id = p.id GROUP BY GROUPING SETS ((p.channel, p.status), (p.channel))) SELECT channel, rows_total, max_cost, CASE WHEN channel RLIKE '^(partner|web)$' THEN 'GROUP_B' WHEN channel RLIKE '^(mobile|store)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS channel_zone FROM rollup_totals ORDER BY max_cost NULLS FIRST, channel_zone;
